<?php require __DIR__.'/../includes/bootstrap.php'; admin_required();
$stats=['contacts'=>(int)db()->query('SELECT COUNT(*) FROM contacts')->fetchColumn(),'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'revenue'=>(int)db()->query("SELECT COALESCE(SUM(amount_paise),0) FROM orders WHERE status='paid'")->fetchColumn()];
$contacts=db()->query('SELECT * FROM contacts ORDER BY created_at DESC LIMIT 50')->fetchAll();$orders=db()->query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 50')->fetchAll();$payments=db()->query('SELECT p.*,o.order_ref,o.customer_name FROM payments p JOIN orders o ON o.id=p.order_id ORDER BY p.created_at DESC LIMIT 50')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="/assets/css/style.css"></head><body class="dashboard"><aside><a class="brand light-brand" href="/"><b>R</b><span>Reliance Digital<small>ADMIN</small></span></a><a href="#contacts">Contacts</a><a href="#orders">Orders</a><a href="#payments">Payments</a><a href="/admin/logout.php">Log out</a></aside><main><div class="admin-head"><div><span class="kicker">DASHBOARD</span><h1>Business overview</h1></div><a class="btn outline" href="/">View website</a></div><div class="stats"><article><span>Contacts</span><b><?=$stats['contacts']?></b></article><article><span>Orders</span><b><?=$stats['orders']?></b></article><article><span>Verified revenue</span><b>₹<?=number_format($stats['revenue']/100)?></b></article></div>
<section id="contacts" class="admin-panel"><h2>Recent contacts</h2><div class="table-wrap"><table><tr><th>Date</th><th>Name</th><th>Contact</th><th>Service</th><th>Message</th></tr><?php foreach($contacts as $c):?><tr><td><?=e($c['created_at'])?></td><td><?=e($c['name'])?></td><td><?=e($c['email'])?><br><?=e($c['phone'])?></td><td><?=e($c['service'])?></td><td><?=e($c['message'])?></td></tr><?php endforeach;?></table></div></section>
<section id="orders" class="admin-panel"><h2>Orders</h2><div class="table-wrap"><table><tr><th>Reference</th><th>Customer</th><th>Package</th><th>Amount</th><th>Status</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['order_ref'])?></td><td><?=e($o['customer_name'])?><br><?=e($o['customer_email'])?></td><td><?=e($o['package_name'])?><br><?=e($o['payment_type'])?></td><td>₹<?=number_format($o['amount_paise']/100)?></td><td><span class="status <?=e($o['status'])?>"><?=e($o['status'])?></span></td></tr><?php endforeach;?></table></div></section>
<section id="payments" class="admin-panel"><h2>Payments</h2><div class="table-wrap"><table><tr><th>Date</th><th>Order</th><th>Customer</th><th>Payment ID</th><th>Status</th></tr><?php foreach($payments as $p):?><tr><td><?=e($p['created_at'])?></td><td><?=e($p['order_ref'])?></td><td><?=e($p['customer_name'])?></td><td><?=e($p['razorpay_payment_id'])?></td><td><?=e($p['status'])?></td></tr><?php endforeach;?></table></div></section></main></body></html>

